"""MinerU Desktop v2.1 — Zotero集成 + 弹性布局 + 批量解析"""
import os, sys, json, time, re, queue, shutil, subprocess, threading, webbrowser
from pathlib import Path
from datetime import datetime

if getattr(sys, "frozen", False):
    base = sys._MEIPASS
    os.environ.setdefault("TCL_LIBRARY", os.path.join(base, "tcl8.6"))
    os.environ.setdefault("TK_LIBRARY", os.path.join(base, "tk8.6"))
    if base not in os.environ.get("PATH", ""):
        os.environ["PATH"] = base + ";" + os.environ.get("PATH", "")

import tkinter as tk
from tkinter import ttk, filedialog, messagebox

V = "2.1.0"

