class MinerUApp:
    def __init__(self):
        self.root=tk.Tk()
        self.root.title(f"MinerU Desktop v{V}")
        self.root.geometry("1020x720")
        self.root.minsize(820,540)
        self.root.configure(bg=C["bg"])
        self.style=setup_ttk()
        self.running=False; self.downloading=False
        self.files=[]; self.zotero_papers=[]
        self.backend_var=tk.StringVar(value="hybrid-auto-engine")
        self.lang_var=tk.StringVar(value="en")
        self.output_var=tk.StringVar(value=str(Path.home()/"Desktop"/"mineru_output"))
        self.log_queue=queue.Queue()
        self.env=detect_env(); self.gpu_info=detect_gpu(); self.model_info=detect_models()

        if not self.env:
            self._build_wizard()
        else:
            self._build_main()
        self._poll_log()

    # ── 安装向导 UI ──
    def _build_wizard(self):
        for w in self.root.winfo_children(): w.destroy()
        top=tk.Frame(self.root,bg=C["surface"],height=48); top.pack(fill="x"); top.pack_propagate(False)
        tk.Label(top,text="⬡  MinerU Desktop — 安装向导",font=("Microsoft YaHei UI",14,"bold"),bg=C["surface"],fg=C["accent"]).pack(side="left",padx=14,pady=10)
        body=tk.Frame(self.root,bg=C["bg"]); body.pack(fill="both",expand=True,padx=40,pady=20)
        tk.Label(body,text="欢迎使用 MinerU Desktop",font=("Microsoft YaHei UI",18,"bold"),bg=C["bg"],fg=C["fg"]).pack()
        tk.Label(body,text="首次运行需要完成环境准备：",font=("Microsoft YaHei UI",10),bg=C["bg"],fg=C["dim"]).pack(pady=(6,20))
        sf=tk.Frame(body,bg=C["surface"]); sf.pack(fill="x",pady=(0,16))
        for t,ok in [("Conda 环境管理器",find_conda()),("NVIDIA 显卡驱动",detect_gpu()["vram_mb"]>0),("MinerU 环境",False),("PyTorch CUDA",False),("AI 模型 (~6GB)",False),("GPU 配置",False)]:
            fr=tk.Frame(sf,bg=C["surface"]); fr.pack(fill="x",padx=14,pady=4)
            tk.Label(fr,text=f"{'✓' if ok else '○'}  {t}",font=("Microsoft YaHei UI",10),bg=C["surface"],fg=C["green"] if ok else C["dim"]).pack(anchor="w")
        self.wp=ttk.Progressbar(body,mode="determinate"); self.wp.pack(fill="x",pady=(8,4))
        self.ws=tk.Label(body,text="点击开始自动安装",font=("Microsoft YaHei UI",9),bg=C["bg"],fg=C["dim"]); self.ws.pack()
        self.wl_fr,self.wl=sb(body,h=10); self.wl_fr.pack(fill="both",expand=True,pady=(10,16))
        self.wb=ttk.Button(body,text="▶ 开始自动安装",command=self._start_wizard,style="Accent.TButton"); self.wb.pack(fill="x",ipady=8)
        self.wlog=self.wl
    def _wlog(self,m): self.log_queue.put(m)
    def _wprog(self,v):
        self.root.after(0,lambda:self.wp.configure(value=v))
        self.root.after(0,lambda:self.ws.config(text="安装中..." if v<100 else "安装完成！切换界面..."))
    def _start_wizard(self):
        self.wb.config(state="disabled",text="安装中...")
        threading.Thread(target=self._run_wizard,daemon=True).start()
    def _run_wizard(self):
        ok=SetupWizard(self._wlog,self._wprog).run(); time.sleep(2)
        self.root.after(0,self._wiz_ok if ok else self._wiz_fail)
    def _wiz_ok(self):
        self.env=detect_env(); self.gpu_info=detect_gpu(); self.model_info=detect_models()
        if not self.env: return self._wiz_fail()
        for w in self.root.winfo_children(): w.destroy()
        self._build_main()
    def _wiz_fail(self):
        self.wb.config(state="normal",text="▶ 重新安装"); self.ws.config(text="安装未完成，检查日志后重试")

    # ── 主界面 ──
    def _build_main(self):
        self._topbar()
        # 用 PanedWindow 实现弹性分栏
        self.pane=tk.PanedWindow(self.root,orient="horizontal",bg=C["border"],sashwidth=3)
        self.pane.pack(fill="both",expand=True,padx=8,pady=(4,0))
        # 左栏 — 可滚动
        left_outer=tk.Frame(self.pane,bg=C["bg"],width=300)
        left_canvas=tk.Canvas(left_outer,bg=C["bg"],highlightthickness=0)
        left_scroll=tk.Scrollbar(left_outer,orient="vertical",command=left_canvas.yview,bg=C["surface"])
        self.left_frame=tk.Frame(left_canvas,bg=C["bg"])
        self.left_frame.bind("<Configure>",lambda e:left_canvas.configure(scrollregion=left_canvas.bbox("all")))
        left_canvas.create_window((0,0),window=self.left_frame,anchor="nw",width=280)
        left_canvas.configure(yscrollcommand=left_scroll.set)
        left_canvas.pack(side="left",fill="both",expand=True)
        left_scroll.pack(side="right",fill="y")
        left_canvas.bind_all("<MouseWheel>",lambda e:left_canvas.yview_scroll(-1*(e.delta//120),"units"))
        self._build_left(self.left_frame)
        self.pane.add(left_outer,width=300,minsize=260)

        # 右栏
        self.right_frame=tk.Frame(self.pane,bg=C["bg"])
        self._build_right(self.right_frame)
        self.pane.add(self.right_frame,width=680,minsize=500)

        self._bottombar()

    def _topbar(self):
        b=tk.Frame(self.root,bg=C["surface"],height=48)
        b.pack(fill="x"); b.pack_propagate(False)
        tk.Label(b,text="⬡  MinerU Desktop",font=("Microsoft YaHei UI",14,"bold"),bg=C["surface"],fg=C["accent"]).pack(side="left",padx=14,pady=10)
        g=self.gpu_info
        if g["cuda_avail"]:
            tk.Label(b,text=f"GPU: {g['gpu_name'][:30]} | {g['vram_mb']}MB",font=("Consolas",9),bg=C["surface"],fg=C["green"]).pack(side="right",padx=14,pady=10)
        m=self.model_info
        ok=m["pipeline"] and m["vlm"]
        tk.Label(b,text=f"模型: {'齐全' if ok else '缺失'}",font=("Consolas",9),bg=C["surface"],fg=C["green"] if ok else C["yellow"]).pack(side="right",padx=4,pady=10)

    def _build_left(self,p):
        # 显卡
        f1=tk.Frame(p,bg=C["surface"]); f1.pack(fill="x",padx=6,pady=(6,0))
        tk.Label(f1,text="🖥 显卡",font=("Microsoft YaHei UI",10,"bold"),bg=C["surface"],fg=C["accent"]).pack(anchor="w",padx=8,pady=(6,0))
        g=self.gpu_info
        self.gl=tk.Label(f1,text=f"设备: {g['gpu_name']}\n显存: {g['vram_mb']}MB\nCUDA: {'可用' if g['cuda_avail'] else '不可用'}",font=("Consolas",8),bg=C["surface"],fg=C["fg"],justify="left"); self.gl.pack(anchor="w",padx=8,pady=(2,4))
