def setup_ttk():
    s=ttk.Style(); s.theme_use("clam")
    s.configure(".",background=C["bg"],foreground=C["fg"],fieldbackground=C["overlay"])
    s.configure("TFrame",background=C["bg"])
    s.configure("TLabel",background=C["bg"],foreground=C["fg"])
    s.configure("TButton",background=C["surface"],foreground=C["fg"],borderwidth=1,padding=(10,5),font=("Microsoft YaHei UI",9))
    s.map("TButton",background=[("active",C["overlay"]),("disabled",C["surface"])],foreground=[("disabled",C["dim"])])
    s.configure("Accent.TButton",background=C["accent"],foreground=C["bg"])
    s.map("Accent.TButton",background=[("active","#89b4fa"),("disabled",C["surface"])])
    s.configure("Green.TButton",background=C["green"],foreground=C["bg"])
    s.configure("Red.TButton",background=C["red"],foreground=C["bg"])
    s.configure("TEntry",fieldbackground=C["overlay"],foreground=C["fg"],insertcolor=C["fg"])
    s.configure("TCombobox",fieldbackground=C["overlay"],foreground=C["fg"],arrowcolor=C["fg"],selectbackground=C["accent"])
    s.map("TCombobox",fieldbackground=[("readonly",C["overlay"])])
    s.configure("TProgressbar",background=C["accent"],troughcolor=C["surface"])
    s.configure("Small.TButton",font=("Microsoft YaHei UI",8),padding=(6,2))
    # Treeview for Zotero papers
    s.configure("Treeview",background=C["overlay"],foreground=C["fg"],fieldbackground=C["overlay"],rowheight=24)
    s.map("Treeview",background=[("selected",C["accent"])],foreground=[("selected",C["bg"])])
    s.configure("Treeview.Heading",background=C["surface"],foreground=C["dim"],font=("Microsoft YaHei UI",9,"bold"))
    return s

def sb(parent,h=5):
    f=tk.Frame(parent,bg=C["bg"])
    t=tk.Text(f,height=h,bg=C["overlay"],fg=C["fg"],font=("Consolas",8),relief="flat",borderwidth=0,wrap="word",state="disabled")
    s=tk.Scrollbar(f,command=t.yview,bg=C["surface"],troughcolor=C["bg"])
    t.configure(yscrollcommand=s.set); t.pack(side="left",fill="both",expand=True); s.pack(side="right",fill="y")
    return f,t

