# ════════════════════════════════════════════════════
# 检测函数
# ════════════════════════════════════════════════════

def find_conda():
    for p in [Path("C:/ProgramData/miniconda3/Scripts/conda.exe"),
              Path("C:/ProgramData/anaconda3/Scripts/conda.exe"),
              Path.home()/"miniconda3/Scripts/conda.exe",
              Path.home()/"anaconda3/Scripts/conda.exe"]:
        if p.exists(): return str(p)
    try:
        r=subprocess.run(["where","conda"],capture_output=True,text=True,timeout=10)
        for ln in r.stdout.strip().split("\n"):
            if ln.strip().lower().endswith("conda.exe"): return ln.strip()
    except: pass
    return None

def detect_env():
    cs=[]
    for b in [Path.home()/".conda"/"envs",
              Path("C:/ProgramData/miniconda3/envs"),
              Path("C:/ProgramData/anaconda3/envs")]:
        if (b/"MinerU"/"python.exe").exists(): cs.append(b/"MinerU")
    for u in Path("C:/Users").iterdir():
        e=u/".conda"/"envs"/"MinerU"
        if (e/"python.exe").exists() and e not in cs: cs.append(e)
    if not cs: return None
    e=cs[0]
    try:
        r=subprocess.run([str(e/"Scripts"/"mineru.exe"),"--version"],
                          capture_output=True,text=True,timeout=15)
        ver=r.stdout.strip()or r.stderr.strip()
    except: ver="(unknown)"
    return {"root":str(e),"python":str(e/"python.exe"),
            "mineru":str(e/"Scripts"/"mineru.exe"),
            "mineru_dl":str(e/"Scripts"/"mineru-models-download.exe"),
            "version":ver,"ok":True}

def detect_gpu():
    info={"gpu_name":"N/A","vram_mb":0,"cuda_avail":False,"driver":"N/A","config_cuda":False}
    try:
        r=subprocess.run(["nvidia-smi","--query-gpu=name,memory.total,driver_version",
            "--format=csv,noheader"],capture_output=True,text=True,timeout=15)
        if r.returncode==0 and r.stdout.strip():
            p=[x.strip()for x in r.stdout.strip().split(",")]
            if len(p)>=2: info["gpu_name"]=p[0]; info["vram_mb"]=int(p[1].replace("MiB","").replace(" ",""))
            if len(p)>=3: info["driver"]=p[2]
    except: pass
    env=detect_env()
    if env:
        try:
            r=subprocess.run([env["python"],"-c","import torch;print(torch.cuda.is_available())"],
                              capture_output=True,text=True,timeout=30)
            if r.returncode==0: info["cuda_avail"]=r.stdout.strip()=="True"
        except: pass
    cp=Path.home()/"mineru.json"
    if cp.exists():
        try:
            c=json.loads(cp.read_text(encoding="utf-8"))
            info["config_cuda"]=c.get("device-mode")=="cuda"
        except: pass
    return info

def detect_models():
    r={"pipeline":False,"vlm":False,"pipeline_mb":0,"vlm_mb":0}
    hf=Path.home()/".cache"/"huggingface"/"hub"
    ms=Path.home()/".cache"/"modelscope"/"hub"/"models"/"OpenDataLab"
    def sz(p):
        try: return sum(f.stat().st_size for f in Path(p).rglob("*")if f.is_file())//1048576
        except: return 0
    for s in hf.glob("models--opendatalab--PDF-Extract-Kit-1.0/snapshots/*"):
        z=sz(s); 
        if z>100: r["pipeline"]=True; r["pipeline_mb"]=z
        break
    p2=ms/"PDF-Extract-Kit-1___0"
    if not r["pipeline"] and p2.exists():
        z=sz(p2)
        if z>100: r["pipeline"]=True; r["pipeline_mb"]=z
    for s in hf.glob("models--opendatalab--MinerU2.5-Pro-2604-1.2B/snapshots/*"):
        z=sz(s)
        if z>100: r["vlm"]=True; r["vlm_mb"]=z
        break
    v2=ms/"MinerU2___5-Pro-2604-1___2B"
    if not r["vlm"] and v2.exists() and (v2/"model.safetensors").exists():
        r["vlm"]=True; r["vlm_mb"]=(v2/"model.safetensors").stat().st_size//1048576
    return r

def parse_zotero_json(filepath):
    """解析 Zotero JSON 文件, 返回 [(citekey, title, pdf_path), ...]"""
    data = json.loads(Path(filepath).read_text(encoding="utf-8"))
    items = data if isinstance(data, list) else data.get("items", [])
    result = []
    for it in items:
        ck = it.get("citationKey", "").strip()
        title = (it.get("title") or "")[:120]
        for att in it.get("attachments", []):
            pp = att.get("path", "")
            if pp.lower().endswith(".pdf") and os.path.exists(pp):
                result.append((ck, title, pp))
                break
    return result

# ════════════════════════════════════════════════════
# 安装向导（同 v2.0）
# ════════════════════════════════════════════════════

class SetupWizard:
    def __init__(self, log_cb, progress_cb):
        self.log=log_cb; self.progress=progress_cb; self._cp=None
    def run(self):
        steps=[("检查 Conda",self._s0),("检查 GPU",self._s1),("创建环境",self._s2),
               ("安装 PyTorch",self._s3),("安装 MinerU",self._s4),
               ("下载模型",self._s5),("启用 CUDA",self._s6)]
        for i,(nm,fn) in enumerate(steps):
            self.log(f"\n── [{i+1}/{len(steps)}] {nm} ──")
            self.progress(int(i/len(steps)*100))
            try: fn()
            except Exception as e: self.log(f"✗ {e}"); self.progress(0); return False
        self.progress(100); self.log("\n✓ 完成！"); return True
    def _run(self,cmd,to=3600):
        e=os.environ.copy(); e["HF_ENDPOINT"]="https://hf-mirror.com"
        p=subprocess.Popen(cmd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,
                           text=True,encoding="utf-8",errors="replace",env=e)
        lp=-1
        for ln in p.stdout:
            ln=ln.strip()
            if ln: self.log("  "+ln)
            m=re.search(r"(\d+)%",ln)
            if m:
                pt=int(m.group(1))
                if pt!=lp: lp=pt; self.progress(pt)
        p.wait(timeout=to); return p.returncode
    def _c(self,a,to=3600):
        if not self._cp: self._cp=find_conda()
        if not self._cp: raise RuntimeError("找不到 Conda")
        return self._run([self._cp]+a,to)
    def _p(self,a,to=600):
        if not self._cp: self._cp=find_conda()
        return self._run([self._cp,"run","-n","MinerU","pip"]+a,to)
    def _m(self,a,to=3600):
        e=detect_env()
        if not e: raise RuntimeError("环境未安装")
        exe=e["mineru_dl"] if a and a[0]!="--version" else e["mineru"]
        return self._run([exe]+a,to)
    def _s0(self):
        p=find_conda()
        if p: self.log(f"✓ Conda: {p}"); self._cp=p
        else: webbrowser.open("https://docs.anaconda.com/miniconda/install/"); raise RuntimeError("请先安装 Miniconda")
    def _s1(self):
        g=detect_gpu()
        if g["vram_mb"]>0: self.log(f"✓ {g['gpu_name']} ({g['vram_mb']}MB)")
        else: self.log("⚠ 无 GPU — 只支持 pipeline")
    def _s2(self):
        if detect_env(): self.log("✓ 环境已存在"); return
        self.log("创建环境 (2-5分钟)..."); self._c(["create","-n","MinerU","python=3.10","-y"],600)
    def _s3(self):
        if detect_gpu()["vram_mb"]==0: self.log("⚠ 跳过"); return
        self.log("安装 PyTorch CUDA (~2.5GB)..."); self._p(["install","torch","torchvision","--index-url","https://download.pytorch.org/whl/cu121"],1200)
    def _s4(self):
        self.log("安装 MinerU..."); self._p(["install","mineru"],600)
    def _s5(self):
        m=detect_models()
        if m["pipeline"] and m["vlm"]: self.log("✓ 模型已齐"); return
        if not m["pipeline"]: self.log("下载 Pipeline (~4GB)..."); self._m(["-s","modelscope","-m","pipeline"])
        if detect_gpu()["vram_mb"]>0 and not m["vlm"]: self.log("下载 VLM (~2.2GB)..."); self._m(["-s","modelscope","-m","vlm"])
    def _s6(self):
        cp=Path.home()/"mineru.json"
        if cp.exists():
            c=json.loads(cp.read_text(encoding="utf-8")); c["device-mode"]="cuda"
            cp.write_text(json.dumps(c,indent=2,ensure_ascii=False),encoding="utf-8")
            self.log("✓ CUDA 已启用")

