        self.ml=tk.Label(f2,text=f"Pipeline: {'✓' if m['pipeline'] else '✗'} {m['pipeline_mb']}MB\nVLM: {'✓' if m['vlm'] else '✗'} {m['vlm_mb']}MB",font=("Consolas",8),bg=C["surface"],fg=C["fg"],justify="left"); self.ml.pack(anchor="w",padx=8,pady=(2,4))
