class MinerUApp:
    def __init__(self):
        self.root=tk.Tk()
        self.root.title(f"MinerU Desktop v{V}")
        self.root.geometry("1020x720")
        self.root.minsize(820,540)
        self.root.configure(bg=C["bg"])
        self.style=setup_ttk()
        self.running=False; self.downloading=False
        self.files=[]; self.zotero_papers=[]
        self.backend_var=tk.StringVar(value="hybrid-auto-engine")
        self.lang_var=tk.StringVar(value="en")
        self.output_var=tk.StringVar(value=str(Path.home()/"Desktop"/"mineru_output"))
        self.log_queue=queue.Queue()
        self.env=detect_env(); self.gpu_info=detect_gpu(); self.model_info=detect_models()

        if not self.env:
            self._build_wizard()
        else:
            self._build_main()
        self._poll_log()

    # ── 安装向导 UI ──
    def _build_wizard(self):
        for w in self.root.winfo_children(): w.destroy()
        top=tk.Frame(self.root,bg=C["surface"],height=48); top.pack(fill="x"); top.pack_propagate(False)
        tk.Label(top,text="⬡  MinerU Desktop — 安装向导",font=("Microsoft YaHei UI",14,"bold"),bg=C["surface"],fg=C["accent"]).pack(side="left",padx=14,pady=10)
        body=tk.Frame(self.root,bg=C["bg"]); body.pack(fill="both",expand=True,padx=40,pady=20)
        tk.Label(body,text="欢迎使用 MinerU Desktop",font=("Microsoft YaHei UI",18,"bold"),bg=C["bg"],fg=C["fg"]).pack()
        tk.Label(body,text="首次运行需要完成环境准备：",font=("Microsoft YaHei UI",10),bg=C["bg"],fg=C["dim"]).pack(pady=(6,20))
        sf=tk.Frame(body,bg=C["surface"]); sf.pack(fill="x",pady=(0,16))
        for t,ok in [("Conda 环境管理器",find_conda()),("NVIDIA 显卡驱动",detect_gpu()["vram_mb"]>0),("MinerU 环境",False),("PyTorch CUDA",False),("AI 模型 (~6GB)",False),("GPU 配置",False)]:
            fr=tk.Frame(sf,bg=C["surface"]); fr.pack(fill="x",padx=14,pady=4)
            tk.Label(fr,text=f"{'✓' if ok else '○'}  {t}",font=("Microsoft YaHei UI",10),bg=C["surface"],fg=C["green"] if ok else C["dim"]).pack(anchor="w")
        self.wp=ttk.Progressbar(body,mode="determinate"); self.wp.pack(fill="x",pady=(8,4))
        self.ws=tk.Label(body,text="点击开始自动安装",font=("Microsoft YaHei UI",9),bg=C["bg"],fg=C["dim"]); self.ws.pack()
        self.wl_fr,self.wl=sb(body,h=10); self.wl_fr.pack(fill="both",expand=True,pady=(10,16))
        self.wb=ttk.Button(body,text="▶ 开始自动安装",command=self._start_wizard,style="Accent.TButton"); self.wb.pack(fill="x",ipady=8)
        self.wlog=self.wl
    def _wlog(self,m): self.log_queue.put(m)
    def _wprog(self,v):
        self.root.after(0,lambda:self.wp.configure(value=v))
        self.root.after(0,lambda:self.ws.config(text="安装中..." if v<100 else "安装完成！切换界面..."))
    def _start_wizard(self):
        self.wb.config(state="disabled",text="安装中...")
        threading.Thread(target=self._run_wizard,daemon=True).start()
    def _run_wizard(self):
        ok=SetupWizard(self._wlog,self._wprog).run(); time.sleep(2)
        self.root.after(0,self._wiz_ok if ok else self._wiz_fail)
    def _wiz_ok(self):
        self.env=detect_env(); self.gpu_info=detect_gpu(); self.model_info=detect_models()
        if not self.env: return self._wiz_fail()
        for w in self.root.winfo_children(): w.destroy()
        self._build_main()
    def _wiz_fail(self):
        self.wb.config(state="normal",text="▶ 重新安装"); self.ws.config(text="安装未完成，检查日志后重试")

    # ── 主界面 ──
    def _build_main(self):
        self._topbar()
        # 用 PanedWindow 实现弹性分栏
        self.pane=tk.PanedWindow(self.root,orient="horizontal",bg=C["border"],sashwidth=3)
        self.pane.pack(fill="both",expand=True,padx=8,pady=(4,0))
        # 左栏 — 可滚动
        left_outer=tk.Frame(self.pane,bg=C["bg"],width=300)
        left_canvas=tk.Canvas(left_outer,bg=C["bg"],highlightthickness=0)
        left_scroll=tk.Scrollbar(left_outer,orient="vertical",command=left_canvas.yview,bg=C["surface"])
        self.left_frame=tk.Frame(left_canvas,bg=C["bg"])
        self.left_frame.bind("<Configure>",lambda e:left_canvas.configure(scrollregion=left_canvas.bbox("all")))
        left_canvas.create_window((0,0),window=self.left_frame,anchor="nw",width=280)
        left_canvas.configure(yscrollcommand=left_scroll.set)
        left_canvas.pack(side="left",fill="both",expand=True)
        left_scroll.pack(side="right",fill="y")
        left_canvas.bind_all("<MouseWheel>",lambda e:left_canvas.yview_scroll(-1*(e.delta//120),"units"))
        self._build_left(self.left_frame)
        self.pane.add(left_outer,width=300,minsize=260)

        # 右栏
        self.right_frame=tk.Frame(self.pane,bg=C["bg"])
        self._build_right(self.right_frame)
        self.pane.add(self.right_frame,width=680,minsize=500)

        self._bottombar()

    def _topbar(self):
        b=tk.Frame(self.root,bg=C["surface"],height=48)
        b.pack(fill="x"); b.pack_propagate(False)
        tk.Label(b,text="⬡  MinerU Desktop",font=("Microsoft YaHei UI",14,"bold"),bg=C["surface"],fg=C["accent"]).pack(side="left",padx=14,pady=10)
        g=self.gpu_info
        if g["cuda_avail"]:
            tk.Label(b,text=f"GPU: {g['gpu_name'][:30]} | {g['vram_mb']}MB",font=("Consolas",9),bg=C["surface"],fg=C["green"]).pack(side="right",padx=14,pady=10)
        m=self.model_info
        ok=m["pipeline"] and m["vlm"]
        tk.Label(b,text=f"模型: {'齐全' if ok else '缺失'}",font=("Consolas",9),bg=C["surface"],fg=C["green"] if ok else C["yellow"]).pack(side="right",padx=4,pady=10)

    def _build_left(self,p):
        # 显卡
        f1=tk.Frame(p,bg=C["surface"]); f1.pack(fill="x",padx=6,pady=(6,0))
        tk.Label(f1,text="🖥 显卡",font=("Microsoft YaHei UI",10,"bold"),bg=C["surface"],fg=C["accent"]).pack(anchor="w",padx=8,pady=(6,0))
        g=self.gpu_info
        self.gl=tk.Label(f1,text=f"设备: {g['gpu_name']}\n显存: {g['vram_mb']}MB\nCUDA: {'可用' if g['cuda_avail'] else '不可用'}",font=("Consolas",8),bg=C["surface"],fg=C["fg"],justify="left"); self.gl.pack(anchor="w",padx=8,pady=(2,4))
        br=tk.Frame(f1,bg=C["surface"]); br.pack(fill="x",padx=8,pady=(0,6))
        ttk.Button(br,text="刷新",command=self._refresh,style="Small.TButton").pack(side="left")
        ttk.Button(br,text="重新安装",command=self._reinstall,style="Small.TButton").pack(side="left",padx=4)

        # 模型
        f2=tk.Frame(p,bg=C["surface"]); f2.pack(fill="x",padx=6,pady=(4,0))
        tk.Label(f2,text="📦 模型",font=("Microsoft YaHei UI",10,"bold"),bg=C["surface"],fg=C["accent"]).pack(anchor="w",padx=8,pady=(6,0))
        m=self.model_info
        self.ml=tk.Label(f2,text=f"Pipeline: {'✓' if m['pipeline'] else '✗'} {m['pipeline_mb']}MB\nVLM: {'✓' if m['vlm'] else '✗'} {m['vlm_mb']}MB",font=("Consolas",8),bg=C["surface"],fg=C["fg"],justify="left"); self.ml.pack(anchor="w",padx=8,pady=(2,4))
        mr=tk.Frame(f2,bg=C["surface"]); mr.pack(fill="x",padx=8,pady=(0,6))
        self.bp=ttk.Button(mr,text="Pipeline",command=lambda:self._download("pipeline"),style="Small.TButton"); self.bp.pack(fill="x",pady=1)
        self.bv=ttk.Button(mr,text="VLM",command=lambda:self._download("vlm"),style="Small.TButton"); self.bv.pack(fill="x",pady=1)
        ttk.Button(mr,text="全部",command=lambda:self._download("all"),style="Small.TButton").pack(fill="x",pady=1)
        self._update_mbtn()

        # 设置
        f3=tk.Frame(p,bg=C["surface"]); f3.pack(fill="x",padx=6,pady=(4,0))
        tk.Label(f3,text="⚙ 设置",font=("Microsoft YaHei UI",10,"bold"),bg=C["surface"],fg=C["accent"]).pack(anchor="w",padx=8,pady=(6,0))
        tk.Label(f3,text="后端",bg=C["surface"],fg=C["dim"],font=("Microsoft YaHei UI",8)).pack(anchor="w",padx=8); 
        ttk.Combobox(f3,textvariable=self.backend_var,state="readonly",values=["hybrid-auto-engine","pipeline","vlm-auto-engine"],font=("Consolas",9),width=24).pack(fill="x",padx=8,pady=2)
        tk.Label(f3,text="语言",bg=C["surface"],fg=C["dim"],font=("Microsoft YaHei UI",8)).pack(anchor="w",padx=8)
        ttk.Combobox(f3,textvariable=self.lang_var,state="readonly",values=["en","ch","ch_server","ch_lite","korean","japan"],font=("Consolas",9),width=24).pack(fill="x",padx=8,pady=2)
        tk.Label(f3,text="输出目录",bg=C["surface"],fg=C["dim"],font=("Microsoft YaHei UI",8)).pack(anchor="w",padx=8,pady=(4,0))
        od=tk.Frame(f3,bg=C["surface"]); od.pack(fill="x",padx=8,pady=(2,6))
        self.oe=ttk.Entry(od,textvariable=self.output_var,font=("Consolas",8))  ## -*- coding: utf-8 -*-
"""MinerU Desktop v2.1 — Zotero集成 + 弹性布局 + 批量解析"""
import os, sys, json, time, re, queue, shutil, subprocess, threading, webbrowser
from pathlib import Path
from datetime import datetime

if getattr(sys, "frozen", False):
    base = sys._MEIPASS
    os.environ.setdefault("TCL_LIBRARY", os.path.join(base, "tcl8.6"))
    os.environ.setdefault("TK_LIBRARY", os.path.join(base, "tk8.6"))
    if base not in os.environ.get("PATH", ""):
        os.environ["PATH"] = base + ";" + os.environ.get("PATH", "")

import tkinter as tk
from tkinter import ttk, filedialog, messagebox

V = "2.1.0"

# ════════════════════════════════════════════════════
C = {"bg":"#1a1b26","surface":"#24283b","overlay":"#2f3346","border":"#3b4261",
     "dim":"#565f89","fg":"#c0caf5","accent":"#7aa2f7","green":"#9ece6a",
     "yellow":"#e0af68","red":"#f7768e","cyan":"#7dcfff"}

# ════════════════════════════════════════════════════
# 检测函数
# ════════════════════════════════════════════════════

def find_conda():
    for p in [Path("C:/ProgramData/miniconda3/Scripts/conda.exe"),
              Path("C:/ProgramData/anaconda3/Scripts/conda.exe"),
              Path.home()/"miniconda3/Scripts/conda.exe",
              Path.home()/"anaconda3/Scripts/conda.exe"]:
        if p.exists(): return str(p)
    try:
        r=subprocess.run(["where","conda"],capture_output=True,text=True,timeout=10)
        for ln in r.stdout.strip().split("\n"):
            if ln.strip().lower().endswith("conda.exe"): return ln.strip()
    except: pass
    return None

def detect_env():
    cs=[]
    for b in [Path.home()/".conda"/"envs",
              Path("C:/ProgramData/miniconda3/envs"),
              Path("C:/ProgramData/anaconda3/envs")]:
        if (b/"MinerU"/"python.exe").exists(): cs.append(b/"MinerU")
    for u in Path("C:/Users").iterdir():
        e=u/".conda"/"envs"/"MinerU"
        if (e/"python.exe").exists() and e not in cs: cs.append(e)
    if not cs: return None
    e=cs[0]
    try:
        r=subprocess.run([str(e/"Scripts"/"mineru.exe"),"--version"],
                          capture_output=True,text=True,timeout=15)
        ver=r.stdout.strip()or r.stderr.strip()
    except: ver="(unknown)"
    return {"root":str(e),"python":str(e/"python.exe"),
            "mineru":str(e/"Scripts"/"mineru.exe"),
            "mineru_dl":str(e/"Scripts"/"mineru-models-download.exe"),
            "version":ver,"ok":True}

def detect_gpu():
    info={"gpu_name":"N/A","vram_mb":0,"cuda_avail":False,"driver":"N/A","config_cuda":False}
    try:
        r=subprocess.run(["nvidia-smi","--query-gpu=name,memory.total,driver_version",
            "--format=csv,noheader"],capture_output=True,text=True,timeout=15)
        if r.returncode==0 and r.stdout.strip():
            p=[x.strip()for x in r.stdout.strip().split(",")]
            if len(p)>=2: info["gpu_name"]=p[0]; info["vram_mb"]=int(p[1].replace("MiB","").replace(" ",""))
            if len(p)>=3: info["driver"]=p[2]
    except: pass
    env=detect_env()
    if env:
        try:
            r=subprocess.run([env["python"],"-c","import torch;print(torch.cuda.is_available())"],
                              capture_output=True,text=True,timeout=30)
            if r.returncode==0: info["cuda_avail"]=r.stdout.strip()=="True"
        except: pass
    cp=Path.home()/"mineru.json"
    if cp.exists():
        try:
            c=json.loads(cp.read_text(encoding="utf-8"))
            info["config_cuda"]=c.get("device-mode")=="cuda"
        except: pass
    return info

def detect_models():
    r={"pipeline":False,"vlm":False,"pipeline_mb":0,"vlm_mb":0}
    hf=Path.home()/".cache"/"huggingface"/"hub"
    ms=Path.home()/".cache"/"modelscope"/"hub"/"models"/"OpenDataLab"
    def sz(p):
        try: return sum(f.stat().st_size for f in Path(p).rglob("*")if f.is_file())//1048576
        except: return 0
    for s in hf.glob("models--opendatalab--PDF-Extract-Kit-1.0/snapshots/*"):
        z=sz(s); 
        if z>100: r["pipeline"]=True; r["pipeline_mb"]=z
        break
    p2=ms/"PDF-Extract-Kit-1___0"
    if not r["pipeline"] and p2.exists():
        z=sz(p2)
        if z>100: r["pipeline"]=True; r["pipeline_mb"]=z
    for s in hf.glob("models--opendatalab--MinerU2.5-Pro-2604-1.2B/snapshots/*"):
        z=sz(s)
        if z>100: r["vlm"]=True; r["vlm_mb"]=z
        break
    v2=ms/"MinerU2___5-Pro-2604-1___2B"
    if not r["vlm"] and v2.exists() and (v2/"model.safetensors").exists():
        r["vlm"]=True; r["vlm_mb"]=(v2/"model.safetensors").stat().st_size//1048576
    return r

def parse_zotero_json(filepath):
    """解析 Zotero JSON 文件, 返回 [(citekey, title, pdf_path), ...]"""
    data = json.loads(Path(filepath).read_text(encoding="utf-8"))
    items = data if isinstance(data, list) else data.get("items", [])
    result = []
    for it in items:
        ck = it.get("citationKey", "").strip()
        title = (it.get("title") or "")[:120]
        for att in it.get("attachments", []):
            pp = att.get("path", "")
            if pp.lower().endswith(".pdf") and os.path.exists(pp):
                result.append((ck, title, pp))
                break
    return result

# ════════════════════════════════════════════════════
# 安装向导（同 v2.0）
# ════════════════════════════════════════════════════

class SetupWizard:
    def __init__(self, log_cb, progress_cb):
        self.log=log_cb; self.progress=progress_cb; self._cp=None
    def run(self):
        steps=[("检查 Conda",self._s0),("检查 GPU",self._s1),("创建环境",self._s2),
               ("安装 PyTorch",self._s3),("安装 MinerU",self._s4),
               ("下载模型",self._s5),("启用 CUDA",self._s6)]
        for i,(nm,fn) in enumerate(steps):
            self.log(f"\n── [{i+1}/{len(steps)}] {nm} ──")
            self.progress(int(i/len(steps)*100))
            try: fn()
            except Exception as e: self.log(f"✗ {e}"); self.progress(0); return False
        self.progress(100); self.log("\n✓ 完成！"); return True
    def _run(self,cmd,to=3600):
        e=os.environ.copy(); e["HF_ENDPOINT"]="https://hf-mirror.com"
        p=subprocess.Popen(cmd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,
                           text=True,encoding="utf-8",errors="replace",env=e)
        lp=-1
        for ln in p.stdout:
            ln=ln.strip()
            if ln: self.log("  "+ln)
            m=re.search(r"(\d+)%",ln)
            if m:
                pt=int(m.group(1))
                if pt!=lp: lp=pt; self.progress(pt)
        p.wait(timeout=to); return p.returncode
    def _c(self,a,to=3600):
        if not self._cp: self._cp=find_conda()
        if not self._cp: raise RuntimeError("找不到 Conda")
        return self._run([self._cp]+a,to)
    def _p(self,a,to=600):
        if not self._cp: self._cp=find_conda()
        return self._run([self._cp,"run","-n","MinerU","pip"]+a,to)
    def _m(self,a,to=3600):
        e=detect_env()
        if not e: raise RuntimeError("环境未安装")
        exe=e["mineru_dl"] if a and a[0]!="--version" else e["mineru"]
        return self._run([exe]+a,to)
    def _s0(self):
        p=find_conda()
        if p: self.log(f"✓ Conda: {p}"); self._cp=p
        else: webbrowser.open("https://docs.anaconda.com/miniconda/install/"); raise RuntimeError("请先安装 Miniconda")
    def _s1(self):
        g=detect_gpu()
        if g["vram_mb"]>0: self.log(f"✓ {g['gpu_name']} ({g['vram_mb']}MB)")
        else: self.log("⚠ 无 GPU — 只支持 pipeline")
    def _s2(self):
        if detect_env(): self.log("✓ 环境已存在"); return
        self.log("创建环境 (2-5分钟)..."); self._c(["create","-n","MinerU","python=3.10","-y"],600)
    def _s3(self):
        if detect_gpu()["vram_mb"]==0: self.log("⚠ 跳过"); return
        self.log("安装 PyTorch CUDA (~2.5GB)..."); self._p(["install","torch","torchvision","--index-url","https://download.pytorch.org/whl/cu121"],1200)
    def _s4(self):
        self.log("安装 MinerU..."); self._p(["install","mineru"],600)
    def _s5(self):
        m=detect_models()
        if m["pipeline"] and m["vlm"]: self.log("✓ 模型已齐"); return
        if not m["pipeline"]: self.log("下载 Pipeline (~4GB)..."); self._m(["-s","modelscope","-m","pipeline"])
        if detect_gpu()["vram_mb"]>0 and not m["vlm"]: self.log("下载 VLM (~2.2GB)..."); self._m(["-s","modelscope","-m","vlm"])
    def _s6(self):
        cp=Path.home()/"mineru.json"
        if cp.exists():
            c=json.loads(cp.read_text(encoding="utf-8")); c["device-mode"]="cuda"
            cp.write_text(json.dumps(c,indent=2,ensure_ascii=False),encoding="utf-8")
            self.log("✓ CUDA 已启用")

