        tk.Label(f3,text="输出目录",bg=C["surface"],fg=C["dim"],font=("Microsoft YaHei UI",8)).pack(anchor="w",padx=8,pady=(4,0))
        od=tk.Frame(f3,bg=C["surface"]); od.pack(fill="x",padx=8,pady=(2,6))
        self.oe=ttk.Entry(od,textvariable=self.output_var,font=("Consolas",8))  # kept as attribute for direct access
        self.oe.pack(side="left",fill="x",expand=True)
