        self.bv=ttk.Button(mr,text="VLM",command=lambda:self._download("vlm"),style="Small.TButton"); self.bv.pack(fill="x",pady=1)
        ttk.Button(mr,text="全部",command=lambda:self._download("all"),style="Small.TButton").pack(fill="x",pady=1)
        self._update_mbtn()

        # 设置
        f3=tk.Frame(p,bg=C["surface"]); f3.pack(fill="x",padx=6,pady=(4,0))
        tk.Label(f3,text="⚙ 设置",font=("Microsoft YaHei UI",10,"bold"),bg=C["surface"],fg=C["accent"]).pack(anchor="w",padx=8,pady=(6,0))
